-- 01단계 canonical fixture 정리 SQL.
-- 아래 식별자는 local-only 예약값이며 운영 사용자/템플릿과 겹치지 않는다.

BEGIN;

-- 승인 RPC가 만든 sales row와 구매 요청을 먼저 제거한다.
DELETE FROM public.template_sales
WHERE template_id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);

DELETE FROM public.template_purchase_requests
WHERE template_id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);

DELETE FROM public.template_access
WHERE template_id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);

DELETE FROM public.template_artists
WHERE template_id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);

DELETE FROM public.template_studio_user_states
WHERE template_id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);

DELETE FROM public.template_studio_document_drafts
WHERE template_id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);

DELETE FROM public.template_studio_assets
WHERE template_id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);

DELETE FROM public.template_studio_document_revisions
WHERE template_id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);

DELETE FROM public.template_studio_documents
WHERE template_id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);

DELETE FROM public.template_plans
WHERE id IN (
  'f0103001-3001-3001-3001-010101010101',
  'f0103002-3002-3002-3002-020202020202'
);

DELETE FROM public.shop_templates
WHERE id IN (
  'f0102001-2001-2001-2001-010101010101',
  'f0102002-2002-2002-2002-020202020202'
)
OR template_id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);

DELETE FROM public.templates
WHERE id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);

DELETE FROM public.artists
WHERE id IN (
  'f0101001-1001-1001-1001-010101010101',
  'f0101002-1002-1002-1002-020202020202'
);

DELETE FROM public.users
WHERE id IN (9190101, 9190102, 9190103, 9190104);

COMMIT;

SELECT 'Remaining canonical 01 fixture templates', COUNT(*)
FROM public.templates
WHERE id IN (
  'f0100001-0101-0101-0101-010101010101',
  'f0100002-0102-0102-0202-020202020202',
  'f0100003-0103-0103-0303-030303030303',
  'f0100004-0104-0104-0404-040404040404',
  'f0100005-0105-0105-0505-050505050505',
  'f0100006-0106-0106-0606-060606060606'
);
